class SaveLoadFrontEnd {
public:
    enum disp_states {
        DSTATE_LSD,
        DSTATE_LOAD,
        DSTATE_LOAD_PICK,
        DSTATE_LOAD_GLOBAL,
        DSTATE_LOADING_GLOBAL,
        DSTATE_LOADING,
        DSTATE_LOAD_DONE,
        DSTATE_SAVE,
        DSTATE_SAVE_GLOBAL,
        DSTATE_SAVE_NAME,
        DSTATE_SAVE_PICK,
        DSTATE_SAVING,
        DSTATE_SAVING_GLOBAL,
        DSTATE_SAVE_PHOTO,
        DSTATE_SAVING_PHOTO,
        DSTATE_SAVE_DONE,
        DSTATE_DELETE,
        DSTATE_DELETE_PICK,
        DSTATE_DELETING,
        DSTATE_DEL_DONE,
        DSTATE_FORMATTING,
        DSTATE_FORM_DONE
    };

private:
    char padding0[0x32b4];
    int forward_menu;
    int forward_sub_menu;
    bool in_frontend;
    char padding1[3];
    int post_format_state;
    char padding2[8];
    int dstate;
    FEMenuSystem *system;
    bool error_thrown;
    char padding3[3];
    int current_error;

public:
    void EndError(int id);
    void SetDState(int state, bool activate = true, bool end_error = false);
    void SetOverwrite(const char *filename = 0);
    void DialogYesOKPressed();
};

__asm__(".equ EndError__16SaveLoadFrontEndi, 0x0019B5A0");
__asm__(".equ SetDState__16SaveLoadFrontEndibT2, 0x0019B760");
__asm__(".equ SetOverwrite__16SaveLoadFrontEndPCc, 0x0019BF50");

void SaveLoadFrontEnd::DialogYesOKPressed()
{
	if(error_thrown)
	{
		EndError( current_error );
	}
	else
	{
		switch(dstate)
		{
			case DSTATE_LOAD_PICK:		SetDState(DSTATE_LOADING); break;
			case DSTATE_LOAD_DONE:
				if (forward_menu == -1)
					SetDState(DSTATE_LOAD);
				else if (forward_sub_menu == -1) system->MakeActive(forward_menu);
				else system->MakeActive(forward_menu, forward_sub_menu);
				break;
			case DSTATE_SAVE_PICK:
				SetOverwrite();
				SetDState(DSTATE_SAVING);
				break;
			case DSTATE_SAVE_DONE:
				if (in_frontend)
				{
					if (forward_menu == -1)
						SetDState(DSTATE_SAVE);
					else if (forward_sub_menu == -1) system->MakeActive(forward_menu);
					else system->MakeActive(forward_menu, forward_sub_menu);
				}
				else
				{
					if (forward_menu == -1)
						system->endDraw(false);
					else
					{
						if (forward_sub_menu == -1)
							system->MakeActive(forward_menu);
						else
							system->MakeActive(forward_menu, forward_sub_menu);
					}
				}
				break;
			case DSTATE_DELETE_PICK:	SetDState(DSTATE_DELETING); break;
			case DSTATE_DEL_DONE:		SetDState(DSTATE_DELETE); break;
		}
	}
}
